INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, 301, 111031, "", "", "独自の改修を施すぞ\n機体の縮小化そして\n各種機能を改良だ", "", "", "", 10, 13010020);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, 301, 0, "", "", 1, "", "", "", "", 13010021);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (3, 301, 111031, "", "", "cmn_pose02_def_N", "", 0.2, "", 1, 13010022);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, 301, 111031, "", "", "ふむ、すなわち\nたい焼きに麦しゅわ\nだが…", "", "", "", 10, 13010023);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, 301, 0, "", "", "", "", "", "", "", 13010024);
