INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, 301, 111031, "", "", "なんたる難題だろう\nぼくの知的探求心が\n疼いてきたと言える", "", "", "", 10, 13010032);
