INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, 302, 13020011, "", "", "", "", "", "", "", 13020014);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, 302, 111031, "", "", "いかんいかん\n資材の山に埋もれて\nしまうところだった", "", "", "", 10, 13020015);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, 302, 0, "", "", "", "", "", "", "", 13020016);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (3, 302, 2, 1, "NoItem", "nyx_302_yuni_02", "", 0.2, "", 0, 13020017);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (3, 302, 111031, 1, "nyx_idle_normal", "nyx_302_yuni_02", "", 0.2, 0.2, 0, 13020018);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, 302, 111031, "", "", "だが怪我の功名、\n探していた部品を\n偶然にも発見できた", "", "", "", 10, 13020019);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (93, 302, 5, "", "", "", "", "", "", "", 13020020);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (4, 302, 111031, "", "", 0, "", "", "", "", 13020021);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (3, 302, 111031, "", "", "nyx_cmn_03", "", 0.2, "", 1, 13020022);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, 302, 111031, "", "", "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", "", "", "", 10, 13020023);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, 302, 0, "", "", "", "", "", "", "", 13020024);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (3, 302, 111031, "", "", "nyx_301_yuni_01", "", 0.2, "", 1, 13020025);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, 302, 111031, "", "", "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", "", "", "", 10, 13020026);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, 302, 0, "", "", 1, "", "", "", "", 13020027);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, 302, 111031, "", "", "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", "", "", "", 10, 13020028);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, 302, 0, "", "", 1, "", "", "", "", 13020029);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (3, 302, 111031, 1, "nyx_302_yuni_04", "nyx_302_yuni_03", "", 0.2, "", 0, 13020030);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, 302, 111031, "", "", "是非もなし\nいざ往かん！", "", "", "", 10, 13020031);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, 302, 0, "", "", 1, "", "", "", "", 13020032);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (93, 302, 1.5, "", "", "", "", "", "", "", 13020033);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, 302, 111031, "", "", "む。奥に入りすぎた\nこれは…出られぬ！\n誰かー！　誰か―！", "", "", "", 10, 13020034);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, 302, 0, "", "", "", "", "", "", "", 13020035);
