INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, 303, 111031, "", "", "ふむ…\n表情映写の動作に\n問題はないようだ", "", "", "", 10, 13030018);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, 303, 0, "", "", "", "", "", "", "", 13030019);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (3, 303, 111031, 1, "nyx_303_yuni_04", "nyx_303_yuni_09", "", 0.2, 0.2, 0, 13030020);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, 303, 111031, "", "", "次はいずれの機能を\n試してみるか…", "", "", "", 10, 13030021);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, 303, 0, "", "", "", "", "", "", "", 13030022);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (93, 303, 0.5, "", "", "", "", "", "", "", 13030023);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, 303, 111031, "", "", "とりあえず適当な\nスイッチを…おっと\nこのボタンはいかん", "", "", "", 10, 13030024);
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (93, 303, 1.5, "", "", "", "", "", "", "", 13030025);
